    },
    I18n: {
        setLang: (l, reload = true) => { 
            App.State.lang = l; localStorage.setItem('se_lang', l); 
            if(App.State.user) App.API.updateLang(l); 
            if(reload) { App.UI.showReload(); } else {
                document.documentElement.setAttribute('dir', l === 'ar' ? 'rtl' : 'ltr'); 
                App.UI.updateIcons(); App.I18n.updateDOM(); App.Cart.render(); App.Catalog.renderBatch(true); App.Cart.renderZones(App.Config.zoneData);
                const bc = document.getElementById('breadcrumbs');
                if(bc && (bc.innerHTML.includes("Home") || bc.innerHTML.includes("Accueil") || bc.innerHTML.includes("الرئيسية"))) { App.Router.go(App.State.currentView || 'home'); }
            }
        },
        t: (key) => { 
            if(!key) return ""; // GUARD CLAUSE FOR NULL KEYS
            let dict = App.State.translations[key]; 
            if (!dict) { const foundKey = Object.keys(App.State.translations).find(k => k.toLowerCase() === key.toLowerCase()); if (foundKey) dict = App.State.translations[foundKey]; }
            if(dict) { const val = dict[App.State.lang]; if(val && (val.includes("#NAME?") || val.includes("#ERROR"))) return dict['en']; return val || dict['en']; }
            return key; 
        },
        updateDOM: () => { 
            // 1. Text Content
            document.querySelectorAll('[data-i18n]').forEach(el => { const key = el.getAttribute('data-i18n'); if(key) el.innerText = App.I18n.t(key); }); 

            // 2. Placeholders - Explicit Mapping (Fixes null crash)
            const phMap = {
                'login-phone': 'ph_phone', 'login-pass': 'ph_password',
                'reg-name': 'ph_name', 'reg-phone': 'ph_phone', 'reg-pass': 'ph_password',
                'addr-name': 'ph_name', 'addr-street': 'ph_address', 'addr-apt': 'ph_address',
                'addr-city': 'lbl_city', 'addr-zip': 'lbl_zip',
                'chk-name': 'ph_name', 'chk-phone': 'ph_phone', 'chk-address': 'ph_address', 'order-note': 'ph_notes',
                'setting-name': 'ph_name', 'setting-email': 'lbl_email'
            };
            Object.keys(phMap).forEach(id => { const el = document.getElementById(id); if(el) el.placeholder = App.I18n.t(phMap[id]); });

            const search = document.getElementById('search-input'); if(search) search.placeholder = App.I18n.t('search_ph') || "Search..."; 
            const typeSel = document.getElementById('addr-type'); if(typeSel) { if(typeSel.options[0]) typeSel.options[0].text = App.I18n.t('lbl_home'); if(typeSel.options[1]) typeSel.options[1].text = App.I18n.t('lbl_office'); }
            const countryInput = document.getElementById('addr-country'); if(countryInput) { const current = countryInput.value; if (!current || current.includes('Morocco') || current.includes('Maroc')) countryInput.value = App.I18n.t('val_morocco'); }
        },
        fetch: () => { fetch(API_URL + '?action=getTranslations').then(r=>r.json()).then(res=>{ if(res.status==='success') { App.State.translations = {...App.State.translations, ...res.data}; App.I18n.updateDOM(); App.Cart.render(); } }); }
    }, 
    Utils: {
        fmt: (price) => { const c = App.State.currency; const l = App.State.lang; const val = (price * App.State.exchange[c]).toFixed(2); if (c === 'MAD') return l === 'ar' ? `${val} د.م.` : `${val} DH`; if (c === 'EUR') return `€${val}`; if (c === 'USD') return `$${val}`; return `${val} ${c}`; },
        save: (key, val) => localStorage.setItem(key, JSON.stringify(val)),
        load: (key) => { try { return JSON.parse(localStorage.getItem(key)) } catch(e) { return null } },
        el: (id) => document.getElementById(id) || { classList: { remove:()=>{}, add:()=>{} }, innerText: '', innerHTML: '', value: '' },
        checkStock: (i) => { if(i.stock === 0) return { disabled: true, badge: `<span class="badge-float badge-out">${App.I18n.t('lbl_sold_out')}</span>` }; if(i.stock < 5) return { disabled: false, badge: `<span class="badge-float badge-low">${App.I18n.t('lbl_low_stock')}</span>` }; if(String(i.tags).includes('on_sale')) return { disabled: false, badge: `<span class="badge-float bg-success">${App.I18n.t('lbl_on_sale')}</span>` }; if(String(i.tags).includes('hot')) return { disabled: false, badge: `<span class="badge-float badge-hot">${App.I18n.t('lbl_hot')}</span>` }; return { disabled: false, badge: '' }; },
        getLocalizedText: (obj) => { if(!obj) return ""; return obj[App.State.lang] || obj['en'] || ""; },
        isValidPhone: (p) => { var clean = String(p).replace(/[\s\-\(\)]/g, ''); return /^(?:(?:\+|00)212|0)[67]\d{8}$/.test(clean); },
        debounce: (func, wait) => { let timeout; return function(...args) { const context = this; clearTimeout(timeout); timeout = setTimeout(() => func.apply(context, args), wait); }; }
    }, 
    UI: {
        toast: (msg, type='info') => { const c = document.getElementById('toast-container'); const t = document.createElement('div'); t.className = `custom-toast border-${type}`; t.innerHTML = `<span>${msg}</span><button type="button" class="btn-close btn-close-sm" onclick="this.parentElement.remove()"></button>`; c.appendChild(t); setTimeout(() => t.remove(), 3000); },
        confirm: (title, msg, callback) => { App.Utils.el('conf-title').innerText = title; App.Utils.el('conf-msg').innerText = msg; const btn = document.getElementById('conf-btn'); const modal = new bootstrap.Modal(document.getElementById('confirmModal')); const newBtn = btn.cloneNode(true); btn.parentNode.replaceChild(newBtn, btn); newBtn.innerText = App.I18n.t('btn_yes'); const cancelBtn = document.querySelector('#confirmModal button[data-i18n="btn_cancel"]'); if(cancelBtn) cancelBtn.innerText = App.I18n.t('btn_cancel'); newBtn.onclick = () => { callback(); modal.hide(); }; modal.show(); },
        setCurrency: (newCurr) => { App.State.lastCurrencyChange = Date.now(); App.State.currency = newCurr; localStorage.setItem('se_curr', newCurr); if(App.State.user) App.API.push('pref'); App.UI.showReload(); },
        selectWelcomeOption: (type, val) => { if(type === 'lang') { App.State.tempLang = val; ['en','fr','ar'].forEach(l => document.getElementById('wel-lang-'+l).classList.remove('selected')); document.getElementById('wel-lang-'+val).classList.add('selected'); const btn = document.getElementById('btn-welcome-start'); if(btn && App.State.translations['btn_start_ordering']) { btn.innerText = App.State.translations['btn_start_ordering'][val]; } } else { App.State.tempCurr = val; ['MAD','EUR','USD'].forEach(c => document.getElementById('wel-curr-'+c).classList.remove('selected')); document.getElementById('wel-curr-'+val).classList.add('selected'); } },
        finishWelcome: () => { const l = App.State.tempLang; const c = App.State.tempCurr; localStorage.setItem('se_setup_done', 'true'); localStorage.setItem('se_lang', l); localStorage.setItem('se_curr', c); location.reload(); },
        updateIcons: () => { const l = App.State.lang; const flagBtn = document.getElementById('header-lang-icon'); if(flagBtn && App.State.flags[l]) flagBtn.src = App.State.flags[l]; const setLangBtn = document.getElementById('setting-lang-icon'); if(setLangBtn && App.State.flags[l]) setLangBtn.src = App.State.flags[l]; const c = App.State.currency; const setCurrDisplay = document.getElementById('setting-curr-display'); if(setCurrDisplay) { if (c === 'MAD') setCurrDisplay.innerText = (l === 'ar') ? "د.م." : "MAD"; else if (c === 'EUR') setCurrDisplay.innerText = "EUR"; else setCurrDisplay.innerText = "USD"; } },
        toggleTheme: () => { const body = document.body; const isDark = body.getAttribute('data-theme') === 'dark'; body.setAttribute('data-theme', isDark ? 'light' : 'dark'); if(document.getElementById('theme-toggle')) document.getElementById('theme-toggle').checked = !isDark; localStorage.setItem('se_theme', !isDark ? 'dark' : 'light'); },
        hideLoader: () => { const l = document.getElementById('global-loader'); if(l) { l.style.opacity = '0'; setTimeout(() => l.remove(), 500); } },
        showReload: () => { let l = document.getElementById('global-loader'); if(!l) { l = document.createElement('div'); l.id = 'global-loader'; l.style.cssText = "position: fixed; top: 0; left: 0; width: 100%; height: 100%; background: var(--bg-body); z-index: 9999; display: flex; flex-direction: column; justify-content: center; align-items: center; opacity: 1;"; document.body.appendChild(l); } l.innerHTML = `<div class='spinner-border text-primary' role='status' style='width:3rem; height:3rem; border-width:4px;'></div><div class='mt-2 fw-bold text-muted'>${App.I18n.t('msg_updating')}</div>`; l.style.display = 'flex'; l.style.opacity = '1'; setTimeout(() => location.reload(), 500); },
        flyToCart: (imgEl) => { if(!imgEl) return; const cartBtn = document.getElementById('nav-cart-btn'); if(!cartBtn) return; const fly = imgEl.cloneNode(); const rect = imgEl.getBoundingClientRect(); fly.classList.add('flying-img'); fly.style.left = rect.left + 'px'; fly.style.top = rect.top + 'px'; fly.style.width = rect.width + 'px'; fly.style.height = rect.height + 'px'; document.body.appendChild(fly); const cartRect = cartBtn.getBoundingClientRect(); setTimeout(() => { fly.style.left = (cartRect.left + 10) + 'px'; fly.style.top = (cartRect.top + 10) + 'px'; fly.style.width = '20px'; fly.style.height = '20px'; fly.style.opacity = '0'; }, 50); setTimeout(() => fly.remove(), 850); },
        updateHearts: (id, isActive) => { document.querySelectorAll(`.wish-btn-card[data-id="${id}"]`).forEach(b => { if(isActive) { b.classList.add('active'); b.innerHTML = '<i class="bi bi-heart-fill text-danger"></i>'; } else { b.classList.remove('active'); b.innerHTML = '<i class="bi bi-heart"></i>'; } }); },
        transition: (cb) => { const grid = document.getElementById('product-grid-root'); if(grid) grid.innerHTML = Array(4).fill('<div class="col-6 col-md-3"><div class="skeleton" style="height:250px"></div></div>').join(''); setTimeout(() => { if(cb) cb(); }, 300); },
        showCartNotification: () => { const n = document.getElementById('cart-notification'); const c = document.getElementById('cn-count'); if(n && c) { c.innerText = App.State.cart.reduce((a,b)=>a+b.qty, 0); n.classList.add('active'); if(App.State.notifyTimeout) clearTimeout(App.State.notifyTimeout); App.State.notifyTimeout = setTimeout(() => { n.classList.remove('active'); }, 5000); } },
        renderCard: (i, isGrid=true) => { 
            const stock = App.Utils.checkStock(i); const isWish = App.State.wishlist.includes(String(i.id)); 
            const heartClass = isWish ? 'active' : ''; const heartIcon = isWish ? 'bi-heart-fill text-danger' : 'bi-heart'; 
            const colClass = isGrid ? 'col-6 col-md-4 col-lg-3' : 'col-6 col-md-3'; 
            const displayTitle = App.Utils.getLocalizedText(i.title); const safeId = String(i.id).replace(/'/g, "\\'");
            let priceHtml = `<span class="text-primary fw-bold">${App.Utils.fmt(i.price_MAD)}</span>`;
            if(i.old_price_MAD > i.price_MAD) priceHtml = `<div class="d-flex align-items-center gap-2"><s class="text-muted small">${App.Utils.fmt(i.old_price_MAD)}</s> <span class="text-danger fw-bold">${App.Utils.fmt(i.price_MAD)}</span></div>`;
            return `<div class="${colClass}"><div class="product-card h-100">${stock.badge}<div class="product-img-wrapper" onclick="App.QuickView.open('${safeId}')"><img src="${i.image || IMG_FALLBACK}" class="product-img img-fade" onload="this.style.opacity=1" loading="lazy" /><button class="wish-btn-card ${heartClass}" data-id="${safeId}" onclick="event.stopPropagation(); event.preventDefault(); App.Wishlist.toggle('${safeId}'); return false;" type="button"><i class="bi ${heartIcon}"></i></button></div><div class="p-3"><div class="star-rating"><i class="bi bi-star-fill"></i><i class="bi bi-star-fill"></i><i class="bi bi-star-fill"></i><i class="bi bi-star-fill"></i><i class="bi bi-star-half"></i> <span class="text-muted small">(4.5)</span></div><h6 class="product-title">${displayTitle}</h6><div class="d-flex justify-content-between align-items-center">${priceHtml}<button class="btn btn-sm btn-dark rounded-circle" ${stock.disabled ? 'disabled="disabled"' : ''} onclick="event.stopPropagation(); event.preventDefault(); App.Cart.add('${safeId}', this); return false;" type="button"><i class="bi bi-plus"></i></button></div></div></div></div>`; 
        },
        renderQuickView: (p) => { 
            const stock = App.Utils.checkStock(p); const displayTitle = App.Utils.getLocalizedText(p.title);
            let rawDesc = App.Utils.getLocalizedText(p.desc); const cleanDesc = rawDesc.replace(/<[^>]*>?/gm, ''); 
            const safeId = String(p.id).replace(/'/g, "\\'");
            let priceHtml = `<div class="h3 text-primary fw-bold m-0" id="qv-price-display">${App.Utils.fmt(p.price_MAD)}</div>`;
            if(p.old_price_MAD > p.price_MAD) priceHtml = `<div class="d-flex align-items-baseline gap-2"><s class="text-muted h5 m-0" id="qv-old-price-display">${App.Utils.fmt(p.old_price_MAD)}</s> <div class="h3 text-danger fw-bold m-0" id="qv-price-display">${App.Utils.fmt(p.price_MAD)}</div></div>`;
            let relatedHtml = ''; const related = App.State.catalog.filter(x => x.category === p.category && x.id !== p.id).slice(0, 2); 
            if(related.length > 0) { relatedHtml = `<div class="mt-4 border-top pt-3"><h6 class="fw-bold mb-3 small text-muted" data-i18n="lbl_related">${App.I18n.t('lbl_related')}</h6><div class="d-flex gap-2">${related.map(r => `<div class="related-item flex-fill" onclick="App.QuickView.open('${String(r.id).replace(/'/g, "\\'")}')"><img src="${r.image || IMG_FALLBACK}" class="related-img"/><div style="min-width:0"><div class="small fw-bold text-truncate">${App.Utils.getLocalizedText(r.title)}</div><div class="small text-primary fw-bold">${App.Utils.fmt(r.price_MAD)}</div></div></div>`).join('')}</div></div>`; } 

            // Reviews Section
            let reviewsHtml = `<div class="mt-4 border-top pt-3"><h6 class="fw-bold mb-3" data-i18n="lbl_reviews">${App.I18n.t('lbl_reviews')}</h6><div id="qv-reviews-list"><div class="spinner-border spinner-border-sm text-primary"></div></div></div>`;

            return `<div class="row g-0" id="qv-content-wrapper"><div class="col-md-5 qv-img-container"><img src="${p.image || IMG_FALLBACK}" class="qv-img img-fade" onload="this.style.opacity=1" style="pointer-events:none; user-select:none;"/></div><div class="col-md-7 p-4 d-flex flex-column"><div class="d-flex justify-content-between align-items-start"><div><h4 class="fw-bold mb-1">${displayTitle}</h4><span class="badge bg-secondary">${App.I18n.t('cat_' + p.category.toLowerCase().replace(/\s+/g, '_'))}</span></div><button class="btn-close" data-bs-dismiss="modal" type="button"></button></div><div class="text-muted small mb-3">${cleanDesc || App.I18n.t('txt_prem_ing')}</div><div class="mb-4"><label class="small fw-bold text-muted mb-2" style="font-size:0.7rem">${App.I18n.t('lbl_size_var')}</label><div class="btn-group w-100 btn-pill-group" role="group"><input type="radio" class="btn-check" name="qv-size" id="size-reg" value="1" checked="checked" onchange="App.QuickView.updatePrice(${p.price_MAD}, ${p.old_price_MAD})"><label class="btn btn-outline-secondary" for="size-reg">${App.I18n.t('opt_regular')}</label><input type="radio" class="btn-check" name="qv-size" id="size-box" value="1.2" onchange="App.QuickView.updatePrice(${p.price_MAD}, ${p.old_price_MAD})"><label class="btn btn-outline-secondary" for="size-box">${App.I18n.t('opt_box')}</label><input type="radio" class="btn-check" name="qv-size" id="size-party" value="1.5" onchange="App.QuickView.updatePrice(${p.price_MAD}, ${p.old_price_MAD})"><label class="btn btn-outline-secondary" for="size-party">${App.I18n.t('opt_party')}</label></div></div><div class="d-flex justify-content-between align-items-center pt-3 border-top mt-auto">${priceHtml}<div class="d-flex gap-2 align-items-center"><div class="input-group input-group-sm" style="width:100px"><button class="btn btn-outline-secondary" type="button" onclick="event.preventDefault(); event.stopPropagation(); App.QuickView.updateQty(-1); return false;">-</button><input type="number" value="1" min="1" id="qv-qty" class="form-control text-center border-0" readonly><button class="btn btn-outline-secondary" type="button" onclick="event.preventDefault(); event.stopPropagation(); App.QuickView.updateQty(1); return false;">+</button></div><button class="btn btn-dark btn-sm rounded-pill fw-bold px-4 py-2" ${stock.disabled ? 'disabled' : ''} type="button" onclick="event.preventDefault(); event.stopPropagation(); App.QuickView.addToCart('${safeId}'); return false;">${App.I18n.t('btn_add_caps')}</button></div></div>${relatedHtml}${reviewsHtml}</div></div></div>`; 
        }
    },
    API: {
        init: () => { App.I18n.updateDOM(); App.I18n.fetch(); fetch(API_URL + '?action=checkStoreStatus').then(r=>r.json()).then(res=>{ if(!res.isOpen) { const b = document.getElementById('store-closed-banner'); if(b) { b.classList.remove('d-none'); b.innerHTML = `<span><i class="bi bi-clock-history me-2"></i> ${App.I18n.t('store_closed_msg')} (${res.hours})</span>`; b.style.cssText = "background: #2d3436; color: #fff; text-align: center; padding: 12px 20px; position: fixed; top: 32px; left: 0; width: 100%; z-index: 1035; font-weight: 700; font-size: 0.9rem; box-shadow: 0 4px 15px rgba(0,0,0,0.2); display: flex; justify-content: center; align-items: center; gap: 10px;"; document.getElementById('main-header').style.top = '80px'; document.body.style.paddingTop = '190px'; } } else { document.getElementById('main-header').style.top = '32px'; document.body.style.paddingTop = '110px'; } if(res.config) { App.Cart.renderZones(res.config); if(res.config.Free_Shipping_Threshold) App.Config.freeShipThreshold = res.config.Free_Shipping_Threshold; } }).catch(() => { }); fetch(API_URL + '?action=getCatalog').then(r=>r.json()).then(res=>{ if(res.status==='success') { App.State.catalog = res.data.map(i => ({ id: i.id, title: i.title, desc: i.desc, category: i.category, price_MAD: parseFloat(i.price_MAD), old_price_MAD: parseFloat(i.old_price_MAD), stock: i.stock, image: i.image, tags: i.tags })); App.Catalog.renderFilters(); App.Catalog.renderBatch(true); App.Recent.render(); if(App.State.user) App.API.syncDown(App.State.user.id); App.UI.hideLoader(); } }).catch(() => { App.UI.toast("API Error", "danger"); App.UI.hideLoader(); }); },
        syncDown: (uid) => { 
            const token = (App.State.user && App.State.user.authToken) ? App.State.user.authToken : '';
            fetch(API_URL + '?action=getUserData&userId='+uid + '&token=' + token).then(r=>r.json()).then(res=>{ if(res.status==='success') { if(res.cart && App.State.cart.length === 0) { App.State.cart = JSON.parse(res.cart); App.Cart.render(); } if(res.wishlist) { App.State.wishlist = String(res.wishlist).split(','); App.Utils.el('nav-wish-count').innerText = App.State.wishlist.length; } if(res.addresses) { App.State.addresses = res.addresses; App.Profile.renderAddresses(); } if(res.orders) { App.State.history = res.orders; App.Profile.renderHistory(); } if(res.profile) { App.State.user.points = res.profile.points || 0; App.Profile.updatePointsUI(); App.State.user.name = res.profile.name; App.State.user.phone = res.profile.phone; if(document.getElementById('setting-name')) document.getElementById('setting-name').value = res.profile.name; if(document.getElementById('setting-phone')) document.getElementById('setting-phone').value = res.profile.phone; if(document.getElementById('setting-email')) document.getElementById('setting-email').value = res.profile.email || ''; if(res.profile.lang) { App.I18n.setLang(res.profile.lang, false); } } } }); 
        },
        push: (type) => { if(!App.State.user) return; let pl = { userId: App.State.user.id, authToken: App.State.user.authToken }; if (type === 'cart') { pl.cartJson = JSON.stringify(App.State.cart); pl.currency = App.State.currency; } else if (type === 'wishlist') { pl.items = App.State.wishlist.join(','); } else if (type === 'pref') { fetch(API_URL, { method: 'POST', body: JSON.stringify({ action: 'updatePreference', data: { userId: App.State.user.id, authToken: App.State.user.authToken, currency: App.State.currency } }) }); return; } fetch(API_URL, {method:'POST', body:JSON.stringify({ action: type==='cart'?'syncCart':'syncWishlist', data: pl })}); },
        updateLang: (lang) => { if(!App.State.user) return; fetch(API_URL, {method:'POST', body:JSON.stringify({ action: 'updateUser', data: { userId: App.State.user.id, authToken: App.State.user.authToken, lang: lang } })}).catch(e=>console.log(e)); },
        checkout: () => { 
            const name = App.Utils.el('chk-name').value; const phone = App.Utils.el('chk-phone').value; const address = App.Utils.el('chk-address').value; const zone = App.Utils.el('chk-zone').value; const payment = document.getElementById('chk-payment') ? document.getElementById('chk-payment').value : 'cod';
            if(!name || !phone || !zone) return alert('Fill all fields'); if(!App.Utils.isValidPhone(phone)) return alert("Invalid Phone. Use 06... or 07..."); if(!address) return alert("Please enter delivery address"); 
            const note = App.Utils.el('order-note').value; const btn = document.getElementById('checkout-btn'); if(btn) { btn.disabled = true; btn.innerText = App.I18n.t('btn_processing'); } 
            const cartData = App.State.cart.map(i => ({ id: i.id, qty: i.qty, variantMult: i.variant.mult, title: i.title })); 
            const orderData = { userId: App.State.user ? App.State.user.id : null, authToken: App.State.user ? App.State.user.authToken : null, name, phone, zone, address: `${zone} - ${address}`, cart: JSON.stringify(cartData), method: payment, couponCode: App.State.activeCoupon ? App.State.activeCoupon.code : null }; 
            fetch(API_URL, { method: 'POST', headers: { "Content-Type": "text/plain;charset=utf-8" }, body: JSON.stringify({ action: 'placeOrder', data: orderData }) }).then(r => r.json()).then(res => { 
                if(res.status === 'success') { 
                    App.State.cart.forEach(c => { if(!App.State.wishlist.includes(String(c.id))) App.State.wishlist.push(String(c.id)); }); App.Utils.save('se_wish', App.State.wishlist); App.API.push('wishlist'); 
                    App.State.cart = []; App.Utils.save('se_cart', []); App.Cart.render(); 
                    const wa_new_order = App.I18n.t('wa_new_order'); const wa_total = App.I18n.t('wa_total'); const wa_1h = App.I18n.t('wa_1h'); 
                    let msg = `*${wa_new_order} ${res.orderId}*%0A`; msg += `👤 ${name} (${phone})%0A🚚 ${orderData.address}%0A💳 ${payment === 'cp' ? 'Cash Plus' : 'COD'}%0A🕒 ${wa_1h}%0A📝 ${note}%0A--------------------%0A`; cartData.forEach(i => msg += `🍱 ${i.qty}x ${i.title}%0A`); msg += `💰 *${wa_total}: ${App.Utils.fmt(res.secureTotal)}*`; 
                    const waLink = `https://wa.me/${App.Config.waNumber}?text=${msg}`;
                    document.getElementById('cart-content').classList.add('d-none'); document.getElementById('cart-empty-state').classList.add('d-none');
                    const container = document.getElementById('cart-module').querySelector('.container');
                    container.innerHTML = `<div class="text-center py-5 fade-in"><div class="mb-4"><i class="bi bi-check-circle-fill text-success display-1"></i></div><h2 class="fw-bold mb-3">${App.I18n.t('msg_order_confirmed')}</h2><p class="text-muted mb-4 lead">${App.I18n.t('msg_order_redirect')}</p><a href="${waLink}" target="_blank" class="btn btn-success rounded-pill px-5 py-3 fw-bold shadow mb-4"><i class="bi bi-whatsapp me-2"></i> ${App.I18n.t('btn_whatsapp')}</a><br/><button class="btn btn-link text-muted text-decoration-none" onclick="location.reload()">${App.I18n.t('btn_back_home')}</button></div>`;
                    const sticky = document.getElementById('sticky-checkout-bar'); if(sticky) sticky.remove();
                } else { alert("Server Error: " + res.message); if(btn) { btn.disabled = false; btn.innerText = App.I18n.t('btn_checkout'); } } 
            }).catch(e => { console.error(e); alert("Connection failed."); if(btn) { btn.disabled = false; btn.innerText = App.I18n.t('btn_checkout'); } }); 
        },
        fetchReviews: (pid) => {
            fetch(API_URL + '?action=getReviews&productId=' + pid).then(r=>r.json()).then(res => {
                const c = document.getElementById('qv-reviews-list');
                if(!c) return;
                if(res.status==='success' && res.data.length > 0) {
                    c.innerHTML = res.data.map(r => `<div class="review-card"><div class="d-flex justify-content-between mb-1"><span class="fw-bold small">${r.user}</span><small class="text-muted">${r.date}</small></div><div class="text-warning small mb-1">${'★'.repeat(r.rating)}${'☆'.repeat(5-r.rating)}</div><p class="m-0 small text-dark">${r.comment}</p></div>`).join('');
                } else {
                    c.innerHTML = '<p class="text-muted small">No reviews yet.</p>';
                }
            });
        },
        submitReview: (orderId, pid) => {
            const rating = prompt("Rating (1-5):");
            if(!rating || rating < 1 || rating > 5) return;
            const comment = prompt(App.I18n.t('ph_review'));
            if(!comment) return;

            // Optimistic Update
            App.UI.toast("Sending review...");

            fetch(API_URL, { method: 'POST', body: JSON.stringify({ action: 'submitReview', data: { userId: App.State.user.id, authToken: App.State.user.authToken, productId: pid, rating: rating, comment: comment, userName: App.State.user.name } }) })
            .then(r=>r.json()).then(res => {
                if(res.status === 'success') { App.UI.toast(App.I18n.t('msg_rev_sub')); }
                else { alert(res.message); }
            });
        }
    },
    Cart: {
        add: (id, btn, qty=1, variant={mult:1, name:'Regular'}) => { const item = App.State.catalog.find(x => String(x.id) === String(id)); if(!item) return; if(btn) { btn.classList.add('btn-clicked'); setTimeout(() => btn.classList.remove('btn-clicked'), 200); } const currentTitle = App.Utils.getLocalizedText(item.title); const cartItem = { ...item, title: currentTitle, qty, variant }; const existIndex = App.State.cart.findIndex(c => c.id === id && c.variant.name === variant.name); if(existIndex > -1) { const newQty = App.State.cart[existIndex].qty + qty; if (newQty <= 0) { App.Cart.remove(existIndex); return; } App.State.cart[existIndex].qty = newQty; } else { if (qty > 0) App.State.cart.push(cartItem); } App.Utils.save('se_cart', App.State.cart); App.Cart.render(); App.API.push('cart'); App.UI.showCartNotification(); if(btn && qty > 0) App.UI.flyToCart(btn.closest('.product-card').querySelector('img')); },
        updateVariant: (idx, el) => { const selectedOption = el.options[el.selectedIndex]; const newMult = parseFloat(selectedOption.value); const newName = selectedOption.text; App.State.cart[idx].variant = { name: newName, mult: newMult }; App.Utils.save('se_cart', App.State.cart); App.Cart.render(); },
        remove: (idx) => { App.UI.confirm(App.I18n.t('cart_remove_title'), App.I18n.t('cart_remove_msg'), () => { App.State.cart.splice(idx, 1); App.Utils.save('se_cart', App.State.cart); App.Cart.render(); App.API.push('cart'); }); },
        empty: () => { if(App.State.cart.length===0) return; App.UI.confirm(App.I18n.t('cart_empty_title'), App.I18n.t('cart_empty_msg'), () => { App.State.cart = []; App.Utils.save('se_cart', []); App.Cart.render(); App.API.push('cart'); }); },
        applyCoupon: () => { const code = App.Utils.el('coupon-code').value.toUpperCase(); const feed = App.Utils.el('coupon-feedback'); feed.innerHTML = 'Verifying...'; fetch(API_URL, {method:'POST', body:JSON.stringify({action:'checkCoupon', data:{code}})}).then(r=>r.json()).then(res=>{ if(res.status==='success') { App.State.activeCoupon = res; feed.innerHTML = `<span class="text-success fw-bold">Active: ${code} (${res.discount*100}% Off)</span>`; App.Cart.calculateTotal(); } else { App.State.activeCoupon = null; feed.innerHTML = `<span class="text-danger">Invalid Code</span>`; } }); },
        renderZones: (config) => { if(config) App.Config.zoneData = config; const data = App.Config.zoneData; if(!data) return; const sel = document.getElementById('chk-zone'); if(!sel) return; sel.innerHTML = `<option value="">${App.I18n.t('select_zone_ph')}</option>`; for(const k in data) { if(k.startsWith('Delivery_')) { const city = k.replace('Delivery_',''); App.Config.deliveryZones[city] = data[k]; const key = 'city_' + city.toLowerCase().replace(/\s+/g, '_'); const translated = App.I18n.t(key); const label = (translated === key) ? city : translated; sel.innerHTML += `<option value="${city}">${label} (+${App.Utils.fmt(data[k])})</option>`; } } },
        fillAddress: () => { const type = document.getElementById('cart-addr-select').value; if(!type) return; if(App.State.addresses && App.State.addresses[type.toLowerCase()]) { const data = App.State.addresses[type.toLowerCase()]; const fullAddr = (typeof data === 'string') ? data : data.full; const userName = (typeof data === 'object' && data.name) ? data.name : App.State.user.name; document.getElementById('chk-name').value = userName; document.getElementById('chk-address').value = fullAddr; } },
        calculateTotal: () => { const zone = App.Utils.el('chk-zone').value; const del = App.Config.deliveryZones[zone] || 0; let sub = App.State.cart.reduce((a,b) => a + (b.price_MAD * b.variant.mult * b.qty), 0); App.Utils.el('cart-subtotal').innerText = App.Utils.fmt(sub); const bar = document.getElementById('delivery-bar-fill'); const msg = document.getElementById('delivery-msg'); const amt = document.getElementById('delivery-amt'); const thresh = App.Config.freeShipThreshold || 200; let finalDel = del; if(sub >= thresh) { finalDel = 0; if(bar) { bar.style.width = '100%'; bar.style.backgroundColor = '#198754'; } if(msg) msg.innerText = "Free Delivery Unlocked!"; if(amt) amt.innerText = ""; } else { const pct = (sub / thresh) * 100; if(bar) bar.style.width = pct + '%'; if(msg) msg.innerText = "Add more for Free Delivery"; if(amt) amt.innerText = App.Utils.fmt(thresh - sub); } let disc = 0; if(App.State.activeCoupon) { disc = sub * App.State.activeCoupon.discount; App.Utils.el('row-disc').classList.remove('d-none'); App.Utils.el('cart-disc').innerText = '-' + App.Utils.fmt(disc); } if(finalDel === 0 && del > 0) { App.Utils.el('cart-delivery').innerHTML = `<s class="text-muted small me-1">${App.Utils.fmt(del)}</s> <span class="text-success fw-bold">${App.I18n.t('lbl_free')}</span>`; } else if(del === 0 && zone === "") { App.Utils.el('cart-delivery').innerText = "--"; } else { App.Utils.el('cart-delivery').innerText = App.Utils.fmt(finalDel); } App.Utils.el('cart-total').innerText = App.Utils.fmt(sub + finalDel - disc); const stickyTotal = document.getElementById('sticky-total-disp'); if(stickyTotal) stickyTotal.innerText = App.Utils.fmt(sub + finalDel - disc); },
        render: () => {
            const list = document.getElementById('cart-list'); const count = App.State.cart.reduce((a,b) => a+b.qty, 0); App.Utils.el('nav-cart-count').innerText = count; App.Utils.el('cn-count').innerText = count; if (App.State.cart.length > 0) { App.Utils.el('cart-empty-state').classList.add('d-none'); App.Utils.el('cart-content').classList.remove('d-none'); } else { App.Utils.el('cart-empty-state').classList.remove('d-none'); App.Utils.el('cart-content').classList.add('d-none'); } let sub = App.State.cart.reduce((a,b) => a + (b.price_MAD * b.variant.mult * b.qty), 0); if(list) { list.innerHTML = App.State.cart.map((i, idx) => { const lineTotal = i.price_MAD * i.variant.mult * i.qty; const safeId = String(i.id).replace(/'/g, "\\'"); return `<div class="cart-item-card"><img src="${i.image || IMG_FALLBACK}" class="cart-item-img img-fade" onload="this.style.opacity=1"/><div class="flex-grow-1 d-flex flex-column justify-content-between"><div class="d-flex justify-content-between align-items-start"><div><h6 class="m-0 fw-bold">${i.title}</h6><select class="form-select form-select-sm border-0 bg-light py-1 ps-2 pe-4" style="font-size:0.75rem; width:auto" onchange="App.Cart.updateVariant(${idx}, this)"><option value="1" ${i.variant.mult===1?'selected':''}>${App.I18n.t('opt_regular')}</option><option value="1.2" ${i.variant.mult===1.2?'selected':''}>${App.I18n.t('opt_box')}</option><option value="1.5" ${i.variant.mult===1.5?'selected':''}>${App.I18n.t('opt_party')}</option></select></div><div class="text-primary fw-bold">${App.Utils.fmt(lineTotal)}</div></div><div class="d-flex justify-content-between align-items-center mt-2"><div class="qty-selector"><button class="qty-btn" onclick="App.Cart.add('${safeId}', null, -1, {mult:${i.variant.mult}, name:'${i.variant.name}'})">-</button><span class="qty-val">${i.qty}</span><button class="qty-btn" onclick="App.Cart.add('${safeId}', null, 1, {mult:${i.variant.mult}, name:'${i.variant.name}'})">+</button></div><div><i class="bi bi-files text-primary action-icon me-2" onclick="App.Cart.add('${safeId}', null, ${i.qty}, {mult:${i.variant.mult}, name:'${i.variant.name}'})"></i><i class="bi bi-trash text-danger action-icon" onclick="App.Cart.remove(${idx})"></i></div></div></div></div>`; }).join(''); } 

            const summaryCard = document.querySelector('.summary-card');
            if(summaryCard && !document.getElementById('chk-payment')) {
                const payDiv = document.createElement('div'); payDiv.className = 'mb-3';
                payDiv.innerHTML = `<label class="small text-muted fw-bold mb-1" data-i18n="lbl_payment_method">${App.I18n.t('lbl_payment_method')}</label><select class="form-select form-select-sm" id="chk-payment"><option value="cod">${App.I18n.t('pay_cod')}</option><option value="cp">${App.I18n.t('pay_cp')}</option></select>`;
                const subRow = summaryCard.querySelector('.summary-row'); if(subRow) summaryCard.insertBefore(payDiv, subRow);
            }
            App.Cart.calculateTotal(); App.Cart.renderZones(); const addrSelect = document.getElementById('cart-addr-select'); if(addrSelect && (App.State.addresses.home || App.State.addresses.office)) { if(addrSelect.options.length <= 1) { addrSelect.innerHTML = `<option value="">${App.I18n.t('select_addr_ph')}</option>`; if(App.State.addresses.home) { const val = (typeof App.State.addresses.home === 'string') ? App.State.addresses.home : App.State.addresses.home.full; addrSelect.innerHTML += `<option value="Home">${App.I18n.t('lbl_home')}: ${val.substring(0, 20)}...</option>`; } if(App.State.addresses.office) { const val = (typeof App.State.addresses.office === 'string') ? App.State.addresses.office : App.State.addresses.office.full; addrSelect.innerHTML += `<option value="Office">${App.I18n.t('lbl_office')}: ${val.substring(0, 20)}...</option>`; } } }
            if(window.innerWidth <= 768 && App.State.currentView === 'cart' && App.State.cart.length > 0) { let sticky = document.getElementById('sticky-checkout-bar'); if(!sticky) { sticky = document.createElement('div'); sticky.id = 'sticky-checkout-bar'; sticky.className = 'sticky-checkout'; document.body.appendChild(sticky); } sticky.style.display = 'flex'; sticky.innerHTML = `<div><small class="text-muted d-block">${App.I18n.t('lbl_total')}</small><span class="fw-bold fs-5 text-primary" id="sticky-total-disp">${App.Utils.fmt(sub)}</span></div><button class="btn btn-success rounded-pill fw-bold px-4" onclick="document.getElementById('checkout-btn').click()">${App.I18n.t('btn_checkout')}</button>`; } else { const sticky = document.getElementById('sticky-checkout-bar'); if(sticky) sticky.style.display = 'none'; }
        }
    },
    Catalog: {
        searchDebounced: null,
        search: (q) => { if(App.Catalog.searchDebounced) App.Catalog.searchDebounced(q); },
        _searchImpl: (q) => { App.State.searchTerm = q.toLowerCase(); App.UI.transition(() => App.Catalog.renderBatch(true)); },
        renderFilters: () => { const c = document.getElementById('category-filters'); if(!c) return; const cats = ['All', ...new Set(App.State.catalog.map(i => i.category))]; c.innerHTML = cats.map(c => { const key = 'cat_' + c.toLowerCase().replace(/\s+/g, '_'); const trans = App.I18n.t(key); const label = (trans && trans !== key) ? trans : c; return `<div class="filter-chip ${c==='All'?'active':''}" onclick="App.Catalog.setCat('${c}', this)">${label}</div>` }).join(''); },
        setCat: (cat, el) => { App.State.activeCat = cat; document.querySelectorAll('.filter-chip').forEach(e => e.classList.remove('active')); el.classList.add('active'); App.UI.transition(() => App.Catalog.renderBatch(true)); },
        renderBatch: (reset=false) => { const grid = document.getElementById('product-grid-root'); if(!grid) return; if(reset) { grid.innerHTML = ''; App.State.visibleCount = 0; } let data = App.State.catalog.filter(i => { const catMatch = (App.State.activeCat === 'All' || i.category === App.State.activeCat); let searchMatch = true; if(App.State.searchTerm) { const txt = (Object.values(i.title).join(' ') + " " + i.tags).toLowerCase(); searchMatch = txt.includes(App.State.searchTerm); } return catMatch && searchMatch; }); const batch = data.slice(App.State.visibleCount, App.State.visibleCount + App.State.batchSize); if(batch.length === 0 && reset) grid.innerHTML = '<div class="col-12 text-center py-5 text-muted">No items found.</div>'; batch.forEach(i => grid.innerHTML += App.UI.renderCard(i)); App.State.visibleCount += App.State.batchSize; }
    },
    Recent: {
        add: (id) => { App.State.recent = App.State.recent.filter(x => x !== id); App.State.recent.unshift(id); if(App.State.recent.length > 4) App.State.recent.pop(); App.Utils.save('se_recent', App.State.recent); App.Recent.render(); },
        render: () => { const c = document.getElementById('recent-grid'); if(!c) return; const items = App.State.catalog.filter(i => App.State.recent.includes(String(i.id))); if(items.length===0) return; c.innerHTML = ''; items.forEach(i => c.innerHTML += App.UI.renderCard(i, false)); }
    }, 
    Router: {
        go: (route) => {
            App.State.currentView = route; window.scrollTo(0,0); document.querySelectorAll('.module-section').forEach(e => e.classList.remove('active'));
            if(route === 'wishlist') { if(App.State.user) { const target = document.getElementById('profile-module'); target.classList.add('active'); setTimeout(() => { const btn = document.querySelector('button[data-bs-target="#tab-wish"]'); if(btn) btn.click(); }, 50); return; } else { alert("Please login to save items."); App.Auth.openModal(); return; } }
            if(route === 'settings') { const target = document.getElementById('settings-module'); target.classList.add('active'); return; }
            const target = document.getElementById(route + '-module'); if(target) target.classList.add('active');
            if(route === 'cart') App.Cart.render(); if(route === 'profile') App.Auth.check();
            const bc = document.getElementById('breadcrumbs'); if(bc) { if (route === 'home') bc.innerHTML = `<span class="fw-bold"><i class="bi bi-house-door-fill"></i> ${App.I18n.t('nav_home')}</span>`; else bc.innerHTML = `<span class="crumb-link" onclick="App.Router.go('home')">${App.I18n.t('nav_home')}</span> <span class="mx-1">/</span> <b class="text-dark text-capitalize">${App.I18n.t('nav_'+route) || route}</b>`; }
        }
    },
    Auth: {
        openModal: () => new bootstrap.Modal(document.getElementById('authModal')).show(),
        login: () => { const p = App.Utils.el('login-phone').value; const pass = App.Utils.el('login-pass').value; if(!p) return alert('Enter Phone'); fetch(API_URL, {method:'POST', body:JSON.stringify({action:'login', data:{phone:p, password:pass}})}).then(r=>r.json()).then(res=>{ if(res.status==='success') { App.State.user = {id:res.userId, name:res.name, phone:p, authToken: res.authToken}; App.Utils.save('se_user', App.State.user); location.reload(); } else alert(res.message); }); },
        register: () => { const n = App.Utils.el('reg-name').value; const p = App.Utils.el('reg-phone').value; const pass = App.Utils.el('reg-pass').value; if(!App.Utils.isValidPhone(p)) return alert("Invalid Phone Number. Use 06... or 07..."); fetch(API_URL, {method:'POST', body:JSON.stringify({action:'register', data:{name:n, phone:p, password:pass}})}).then(r=>r.json()).then(res=>{ if(res.status==='success') { App.State.user = {id:res.userId, name:n, phone:p, authToken: res.authToken}; App.Utils.save('se_user', App.State.user); location.reload(); } else alert(res.message); }); },
        logout: () => { App.UI.confirm(App.I18n.t('logout_title'), App.I18n.t('logout_msg'), () => { localStorage.removeItem('se_user'); location.reload(); }); },
        check: () => { const u = App.State.user; if(u) { App.Utils.el('profile-logged-in').style.display = 'block'; App.Utils.el('profile-logged-out').style.display = 'none'; App.Utils.el('user-name-display').innerText = u.name; App.Utils.el('user-phone-display').innerText = u.phone; App.Utils.el('auth-btn').innerHTML = '<i class="bi bi-person-check-fill text-success fs-5"></i>'; App.Utils.el('setting-user-id').innerText = u.id.substring(0,8)+'...'; App.Profile.renderHistory(); if(App.Wishlist && typeof App.Wishlist.render === 'function') App.Wishlist.render(); App.Profile.renderAddresses(); App.Profile.updatePointsUI(); const addrSelect = document.getElementById('cart-addr-select'); if(addrSelect && (App.State.addresses.home || App.State.addresses.office)) { addrSelect.innerHTML = `<option value="">${App.I18n.t('select_addr_ph')}</option>`; if(App.State.addresses.home) addrSelect.innerHTML += `<option value="Home">${App.I18n.t('lbl_home')}: ${typeof App.State.addresses.home === 'string' ? App.State.addresses.home : App.State.addresses.home.full}</option>`; } if(App.State.addresses.office) addrSelect.innerHTML += `<option value="Office">${App.I18n.t('lbl_office')}: ${typeof App.State.addresses.office === 'string' ? App.State.addresses.office : App.State.addresses.office.full}</option>`; } }
    },
    Profile: {
        openAddressModal: (addrType = null) => { const modalEl = document.getElementById('addressModal'); const modal = bootstrap.Modal.getOrCreateInstance(modalEl); if(addrType) { const data = App.State.addresses[addrType.toLowerCase()]; if(data && typeof data === 'object') { const getEl = (id) => document.getElementById(id); if(getEl('addr-name')) getEl('addr-name').value = data.name || ''; if(getEl('addr-street')) getEl('addr-street').value = data.street || ''; if(getEl('addr-apt')) getEl('addr-apt').value = data.apt || ''; if(getEl('addr-city')) getEl('addr-city').value = data.city || ''; if(getEl('addr-zip')) getEl('addr-zip').value = data.zip || ''; if(getEl('addr-country')) getEl('addr-country').value = data.country || ''; if(getEl('addr-type')) getEl('addr-type').value = addrType; } } modal.show(); },
        renderAddresses: () => { const c = document.getElementById('address-list-grid'); if(!c) return; const a = App.State.addresses; let html = ''; if(a.home) html += App.Profile.createAddrCard('Home', a.home); if(a.office) html += App.Profile.createAddrCard('Office', a.office); if(!html) html = `<div class="col-12 text-center text-muted py-3">${App.I18n.t('addr_empty')}</div>`; c.innerHTML = html; App.I18n.updateDOM(); },
        createAddrCard: (type, data) => { const display = (typeof data === 'string') ? data : (data.full || `${data.street} ${data.apt}<br>${data.city}, ${data.zip}`); const labelKey = type === 'Home' ? 'lbl_home' : 'lbl_office'; return `<div class="col-md-6"><div class="address-card"><span class="address-tag" data-i18n="${labelKey}">${App.I18n.t(labelKey)}</span><h6 class="fw-bold mb-3"><i class="bi bi-geo-alt-fill"></i> ${data.name || type}</h6><p class="small text-muted mb-3">${display}</p><button class="btn btn-sm btn-outline-dark rounded-pill px-3" onclick="App.Profile.openAddressModal('${type}')" data-i18n="btn_edit">Edit</button></div></div>`; },
        saveAddress: () => { if(!App.State.user) return alert("Please login first"); const btn = document.getElementById('save-addr-btn'); if(btn) { btn.disabled = true; btn.innerText = App.I18n.t('btn_saving'); } const getVal = (id) => { const el = document.getElementById(id); return el ? el.value : ""; }; const type = getVal('addr-type'); const addrData = { name: getVal('addr-name'), street: getVal('addr-street'), apt: getVal('addr-apt'), city: getVal('addr-city'), zip: getVal('addr-zip'), country: getVal('addr-country'), full: `${getVal('addr-street')} ${getVal('addr-apt')}, ${getVal('addr-city')}` }; if(!addrData.street) { if(btn) { btn.disabled = false; btn.innerText = App.I18n.t('btn_save_addr'); } return alert('Enter Street Address'); } fetch(API_URL, {method:'POST', body:JSON.stringify({ action: 'updateAddress', data: { userId: App.State.user.id, authToken: App.State.user.authToken, type: type, addressJson: JSON.stringify(addrData) } })}).then(r=>r.json()).then(res=>{ if(res.status==='success') { if(type==='Home') App.State.addresses.home = addrData; else App.State.addresses.office = addrData; App.Profile.renderAddresses(); bootstrap.Modal.getInstance(document.getElementById('addressModal')).hide(); App.UI.toast('Address Saved'); } else { alert("Save failed: " + res.message); } if(btn) { btn.disabled = false; btn.innerText = App.I18n.t('btn_save_addr'); } }).catch(e => { alert("Error saving"); if(btn) btn.disabled = false; }); },
        saveSettings: () => { if(!App.State.user) return; const btn = document.getElementById('save-settings-btn'); if(btn) { btn.disabled = true; btn.innerText = App.I18n.t('btn_saving'); } const n = document.getElementById('setting-name').value; const e = document.getElementById('setting-email').value; const p = document.getElementById('setting-phone').value; fetch(API_URL, {method:'POST', body:JSON.stringify({ action: 'updateUser', data: { userId: App.State.user.id, authToken: App.State.user.authToken, name: n, email: e, phone: p } })}).then(r=>r.json()).then(res=>{ if(res.status==='success') App.UI.toast(App.I18n.t('msg_settings_saved')); if(btn) { btn.disabled = false; btn.innerText = App.I18n.t('btn_save_changes'); } }); },
        renderHistory: () => { const list = document.getElementById('order-history-list'); if(!list) return; if(App.State.history.length === 0) { list.innerHTML = '<p class="text-muted small py-2">No orders found.</p>'; return; } list.innerHTML = ''; App.State.history.forEach(o => { const displayTotal = App.Utils.fmt(parseFloat(o.total)) || "0.00 DH"; let thumbsHtml = ''; try { const items = JSON.parse(o.items); if(items && items.length) { thumbsHtml = items.slice(0, 3).map(itemName => { var img = IMG_FALLBACK; for (var k = 0; k < App.State.catalog.length; k++) { var prod = App.State.catalog[k]; if ((typeof prod.title === 'object' && (itemName.includes(prod.title.en) || itemName.includes(prod.title.fr) || itemName.includes(prod.title.ar))) || (typeof prod.title === 'string' && itemName.includes(prod.title))) { img = prod.image; break; } } return `<img src="${img}" class="order-thumb-img"/>`; }).join(''); } } catch(e) {} const statusClass = (o.status === 'Completed' || o.status === 'Sent') ? 'status-pill-completed' : 'status-pill-processing'; list.innerHTML += `<div class="order-card-modern"><div class="d-flex justify-content-between mb-3"><span class="fw-bold text-dark">#${o.id}</span><span class="text-muted small">${new Date(o.date).toLocaleDateString()}</span></div><div class="order-thumbs d-flex gap-2 mb-3">${thumbsHtml}</div><div class="d-flex justify-content-between align-items-center mb-2"><span class="text-muted">${App.I18n.t('lbl_status')}</span><span class="${statusClass}">${App.I18n.t('status_' + o.status.toLowerCase()) || o.status}</span></div><div class="d-flex justify-content-between align-items-center mb-3"><span class="text-muted">${App.I18n.t('lbl_total')}</span><span class="fw-bold fs-5">${displayTotal}</span></div><div class="d-flex gap-2"><button class="btn btn-primary flex-grow-1 rounded-pill" onclick="App.Profile.showOrderDetail('${o.id}')">${App.I18n.t('btn_track')}</button><button class="btn btn-light flex-grow-1 rounded-pill" onclick="App.Profile.showOrderDetail('${o.id}')">${App.I18n.t('btn_details')}</button></div></div>`; }); },
        showOrderDetail: (id) => { 
            const o = App.State.history.find(x => x.id === id); if(!o) return; let itemsHtml = '<p class="text-muted">No item details.</p>'; try { const items = JSON.parse(o.items); if(items && items.length) { itemsHtml = `<div class="bg-light p-3 rounded mb-3">` + items.map(i => { let title = i; let qty =1; if(i.match(/^\d+x/)) { let parts = i.split('x '); qty = parseInt(parts[0]); title = parts.slice(1).join('x '); } let match = null; for (let k = 0; k < App.State.catalog.length; k++) { const p = App.State.catalog[k]; if (typeof p.title === 'object') { if ((p.title.en && title.includes(p.title.en)) || (p.title.fr && title.includes(p.title.fr)) || (p.title.ar && title.includes(p.title.ar))) { match = p; break; } } else if (typeof p.title === 'string' && title.includes(p.title)) { match = p; break; } } const img = match ? (match.image || IMG_FALLBACK) : IMG_FALLBACK; const unitPrice = match ? match.price_MAD : 0; const subtotal = unitPrice * qty; const displayPrice = unitPrice > 0 ? App.Utils.fmt(subtotal) : ''; 
            const reviewBtn = (o.status === 'Completed' && match) ? `<button class="btn btn-link btn-sm text-decoration-none p-0 ms-2" onclick="App.API.submitReview('${o.id}', '${match.id}')"><small>★ ${App.I18n.t('btn_write_review')}</small></button>` : '';
            return `<div class="order-detail-row"><img src="${img}" class="od-img"/><div><div class="fw-bold small">${title}</div><div class="text-primary small fw-bold">${displayPrice} ${reviewBtn}</div></div></div>`; }).join('') + `</div>`; } } catch(e) {} 
            let totalVal = parseFloat(o.total); if (isNaN(totalVal)) totalVal = 0; const displayTotalTotal = App.Utils.fmt(totalVal);

            // Timeline Logic
            const statuses = ['Pending', 'Preparing', 'On the Way', 'Delivered'];
            let currentStep = statuses.indexOf(o.status);
            if(o.status === 'Completed' || o.status === 'Sent') currentStep = 3;
            if(currentStep === -1) currentStep = 0;

            const timelineHtml = `<div class="timeline">` + statuses.map((s, idx) => {
                const isActive = idx <= currentStep ? 'active' : '';
                const timeLabel = idx === 0 ? new Date(o.date).toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'}) : '';
                return `<div class="timeline-item ${isActive}"><span class="small ${isActive ? 'fw-bold text-success' : 'text-muted'}">${App.I18n.t('time_' + (idx===2?'way': (idx===3?'del': (idx===1?'prep':'placed'))))}</span> <span class="small text-muted ms-2">${timeLabel}</span></div>`;
            }).join('') + `</div>`;

            const html = `<div class="p-3"><div class="d-flex justify-content-between align-items-center mb-3"><h5 class="m-0 fw-bold">#${o.id}</h5><span class="badge bg-primary">${App.I18n.t('status_' + o.status.toLowerCase()) || o.status}</span></div><h6 class="small fw-bold text-muted mb-2 text-uppercase" data-i18n="lbl_timeline">${App.I18n.t('lbl_timeline')}</h6>${timelineHtml}${itemsHtml}<div class="d-flex justify-content-between fw-bold border-top pt-3"><span>${App.I18n.t('total_caps')}</span><span class="text-primary">${displayTotalTotal}</span></div><button class="btn btn-outline-dark w-100 rounded-pill mt-4" data-bs-dismiss="modal" data-i18n="btn_close">Close</button></div>`; 
            document.getElementById('order-detail-body').innerHTML = html; new bootstrap.Modal(document.getElementById('orderDetailModal')).show(); App.I18n.updateDOM(); 
        },
        updatePointsUI: () => {
            const el = document.querySelector('.profile-info .sub-link');
            if(el && App.State.user) {
                el.innerHTML = `<span class="points-badge"><i class="bi bi-star-fill me-1"></i> ${App.State.user.points} ${App.I18n.t('lbl_pts')}</span>`;
            }
        }
    },
    QuickView: {
        open: (id) => { 
            const p = App.State.catalog.find(x => String(x.id) === String(id)); 
            if(!p) return; 
            App.Recent.add(id); 
            document.getElementById('qv-body').innerHTML = App.UI.renderQuickView(p); 
            new bootstrap.Modal(document.getElementById('quickViewModal')).show(); 
            // FETCH REVIEWS ON OPEN
            App.API.fetchReviews(id);
        },
        updatePrice: (base, oldBase) => { 
            const mult = parseFloat(document.querySelector('input[name="qv-size"]:checked').value); 
            document.getElementById('qv-price-display').innerText = App.Utils.fmt(base * mult); 
            const oldEl = document.getElementById('qv-old-price-display');
            if(oldEl && oldBase) oldEl.innerText = App.Utils.fmt(oldBase * mult);
        },
        updateQty: (delta) => {
            const el = document.getElementById('qv-qty');
            if(!el) return;
            let val = parseInt(el.value) ||1;
            val += delta;
            if(val < 1) val = 1;
            el.value = val;
        },
        addToCart: (id) => { 
            const qtyInput = document.getElementById('qv-qty');
            let sizeInput = document.querySelector('input[name="qv-size"]:checked');
            if(!sizeInput) sizeInput = document.getElementById('size-reg'); 

            const qty = qtyInput ? parseInt(qtyInput.value) : 1;
            const el = sizeInput || { value: 1, id: 'size-reg' }; 

            let labelText = "Regular";

            if(sizeInput) {
                    const label = document.querySelector(`label[for="${sizeInput.id}"]`);
                    if(label) labelText = label.innerText;
            }
            const variant = { mult: parseFloat(el.value), name: labelText }; 
            App.Cart.add(id, null, qty, variant); 
            bootstrap.Modal.getInstance(document.getElementById('quickViewModal')).hide(); 
        }
    },
    Wishlist: { toggle: (id) => { const strId = String(id); const idx = App.State.wishlist.indexOf(strId); const isActive = (idx !== -1); if(isActive) { App.State.wishlist.splice(idx,1); App.UI.toast(App.I18n.t('msg_wish_removed')); } else { App.State.wishlist.push(strId); App.UI.toast(App.I18n.t('msg_wish_added')); } App.Utils.save('se_wish', App.State.wishlist); App.Utils.el('nav-wish-count').innerText = App.State.wishlist.length; App.UI.updateHearts(strId, !isActive); App.API.push('wishlist'); if(document.getElementById('profile-wishlist-grid') && document.getElementById('profile-wishlist-grid').offsetParent !== null) App.Wishlist.render(); }, render: () => { let container = document.getElementById('wishlist-grid'); if(document.getElementById('profile-wishlist-grid') && document.getElementById('profile-wishlist-grid').offsetParent !== null) container = document.getElementById('profile-wishlist-grid'); if(!container) return; container.innerHTML = ''; const items = App.State.catalog.filter(p => App.State.wishlist.includes(String(p.id))); if(items.length === 0) { container.innerHTML = `<p class="text-center text-muted mt-5 col-12" data-i18n="wishlist_empty">${App.I18n.t('wishlist_empty')}</p>`; return; } items.forEach(i => container.innerHTML += App.UI.renderCard(i)); }, clear: () => { if(App.State.wishlist.length === 0) return; App.UI.confirm(App.I18n.t('wish_clear_title'), App.I18n.t('wish_clear_msg'), () => { App.State.wishlist=[]; App.Utils.save('se_wish',[]); App.Wishlist.render(); App.API.push('wishlist'); }); } }
};

document.addEventListener('DOMContentLoaded', () => {
    if (typeof AOS !== 'undefined') { AOS.init(); }
    App.Catalog.searchDebounced = App.Utils.debounce(App.Catalog._searchImpl, 300);
    App.State.cart = App.Utils.load('se_cart') || [];
    App.State.wishlist = App.Utils.load('se_wish') || [];
    App.State.recent = App.Utils.load('se_recent') || [];
    App.State.user = App.Utils.load('se_user');

    if (!localStorage.getItem('se_setup_done')) {
        const browserLang = navigator.language.slice(0,2);
        if (['en', 'fr', 'ar'].includes(browserLang)) {
            App.State.tempLang = browserLang;
            setTimeout(() => {
                 ['en','fr','ar'].forEach(l => document.getElementById('wel-lang-'+l)?.classList.remove('selected'));
                 document.getElementById('wel-lang-'+browserLang)?.classList.add('selected');
                 const btn = document.getElementById('btn-welcome-start');
                 if(btn) btn.innerText = App.State.translations['btn_start_ordering'][browserLang];
            }, 500);
        }
        const welcomeModal = new bootstrap.Modal(document.getElementById('welcomeModal'));
        welcomeModal.show();
    } else {
        App.State.lang = localStorage.getItem('se_lang') || 'en';
        const storedCurr = localStorage.getItem('se_curr');
        if(storedCurr) { App.State.currency = storedCurr; }
        if(App.State.wishlist) App.Utils.el('nav-wish-count').innerText = App.State.wishlist.length;
        const storedTheme = localStorage.getItem('se_theme');
        if(storedTheme) { document.body.setAttribute('data-theme', storedTheme); if(document.getElementById('theme-toggle')) document.getElementById('theme-toggle').checked = (storedTheme === 'dark'); }
        document.documentElement.setAttribute('dir', App.State.lang === 'ar' ? 'rtl' : 'ltr');
        App.UI.updateIcons();
    }

    App.Router.go('home');
    App.API.init();
    App.Auth.check();
    App.Cart.render();
});
